import{z as o,x as s,o as e,c as d,q as r,j as n,D as E,d as B,s as i,S as l,b as A}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"执行案例与收束","description":"","frontmatter":{"title":"执行案例与收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ex-case-map.md","filePath":"quant/ex-case-map.md","lastUpdated":1791063341000}'),C={name:"quant/ex-case-map.md"};function p(h,a,u,c,m,f){const t=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=r('<h1 id="执行案例与收束" tabindex="-1">执行案例与收束 <a class="header-anchor" href="#执行案例与收束" aria-label="Permalink to &quot;执行案例与收束&quot;">​</a></h1><div class="epigraph"><p>案例是把参数表放回日历里：同一个算法，在指数日、恐慌日与涨跌停日是三种产品；执行的学问不在公式的深度，而在状态识别与规则的前置。</p><footer>—— 据 Harris, *Trading and Exchanges* 对执行实务的论述与本课程各课口径整理</footer></div><p><a href="/quant/ex-optimal-conversion-deep">上一课</a>把最优转换收在「最优只对声明的目标与约束成立」；本课程到此收束。收束前用三个案例把各课的维度放回日历——每个案例都是前面若干课的一次合演，也是一张可自查的清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单看任何一课的规则，落地时都会遇到「多条规则同时触发」的时刻：调度要加速、毒性门控要减速、风险预算要前倾、合规要留痕。案例的价值不在故事，在冲突的裁决顺序：两条规则指向相反动作时，哪条让路。三个案例代表三类常见冲突——收益与拥挤、速度与恐惧、制度与模型。</p><p><span class="marginnote">「裁决顺序」可以类比飞行员的检查单文化：引擎告警与襟翼故障同时出现时，先处理哪个不靠机长临场发挥，而是演练过无数次的优先级表。执行员在恐慌窗口里同样不该现场辩论「要不要追赶进度」，答案应该早已写进状态机。</span></p><h3 id="案例一-指数纳入日" tabindex="-1">案例一：指数纳入日 <a class="header-anchor" href="#案例一-指数纳入日" aria-label="Permalink to &quot;案例一：指数纳入日&quot;">​</a></h3><p>公告后两周，纳入生效日的收盘竞价集中了跟踪组合的强制买盘。合演的各课：配额提前锁定，收盘腿按 <a href="/quant/ex-auction-execution">竞价执行</a> 用预测竞价量做分母，虚拟匹配只调整未承诺量；期货做领先腿拿到暴露，再按 <a href="/quant/ex-multiasset">多资产执行</a> 的兑换节奏换回篮子，基差偏离持有成本时放缓；成分股的连续段用 <a href="/quant/arrival-price">到达价格算法</a> 前倾但封参与率——所有人都知道这天有同向流，<a href="/quant/ex-cost-forecast">成本预测模型</a> 校准于普通日的 \\(\\eta\\) 会低估，保守分位上调。事后 TCA 按「指数日」单独成层，不进常规均值。</p><h3 id="案例二-宏观数据日的恐慌窗口" tabindex="-1">案例二：宏观数据日的恐慌窗口 <a class="header-anchor" href="#案例二-宏观数据日的恐慌窗口" aria-label="Permalink to &quot;案例二：宏观数据日的恐慌窗口&quot;">​</a></h3><p>CPI 或议息公布后五分钟，价差翻倍、深度撤走。合演：<a href="/quant/ex-vol-execution">波动执行的专门问题</a> 的状态触发切到预登记参数——价差围栏收紧、参与上限下调；<a href="/quant/ex-slice-scheduling-deep">子单调度的深化</a> 的毒性门控压住追赶冲动，deadline 策略接管剩余量；暗腿按 <a href="/quant/ex-dark-execution">暗池执行</a> 的漂移传感器压缩份额，避免把暴露留给柠檬时刻。裁决顺序在此显形：完成率让位于价格保护——恐慌日少完成的部分是机会成本，穿过五档的部分是永久成本。</p><h3 id="案例三-a-股涨跌停与撤单率" tabindex="-1">案例三：A 股涨跌停与撤单率 <a class="header-anchor" href="#案例三-a-股涨跌停与撤单率" aria-label="Permalink to &quot;案例三：A 股涨跌停与撤单率&quot;">​</a></h3><p>持仓组合里的名字封板，卖不出；程序化报备与撤单率监控约束改单频率。合演：触板是吸收态，<a href="/quant/ex-optimal-conversion-deep">最优转换的深化</a> 的带停时框架接管——排队等开板或顺延次日，不可执行记成制度未完成而不是算法失败，见 <a href="/quant/cn-limit-liquidity-hole">涨跌停与流动性黑洞</a>；防御性撤单按 <a href="/quant/cn-fee-cancel-ratio">差异化收费与撤单率监控</a> 留痕；对冲腿走期货维持 <a href="/quant/ex-multiasset">多资产执行</a> 的暴露带，现货腿等开板。硬件层保证状态机不因行情风暴丢回执，见 <a href="/quant/ex-hardware">硬件与执行</a>。</p><p><span class="marginnote">三个案例共用一张裁决表：价格保护优先于完成率，制度约束优先于模型最优，留痕义务优先于参数自由。顺序写进状态机，而不是留给临场判断。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把案例沉淀为清单，交接与复盘都过一遍：参照价与锁定时点；完成政策与放弃权限；分层口径（体制、日期类型）；参数的冻结清单与触发清单；对冲与同步约束；合规留痕。清单对应本课程的轴：谱系给维度，调度给修正，暗池与竞价给场所，波动与多资产给状态，TCA 给度量，硬件给预算，成本模型给事前，最优转换给控制。十一个课名就是清单的十一个格子。</p>',15)),(e(),n(l,null,{default:E(()=>[i(t,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20CASE%7B%22%E6%97%A5%E5%8E%86%E7%8A%B6%E6%80%81%22%7D%0A%20%20CASE%20--%3E%7C%E6%8C%87%E6%95%B0%E6%97%A5%7C%20A%5B%22%E9%85%8D%E9%A2%9D%20%2B%20%E9%A2%86%E5%85%88%E8%85%BF%20%2B%20%E4%BF%9D%E5%AE%88%E5%88%86%E4%BD%8D%E6%88%90%E6%9C%AC%22%5D%0A%20%20CASE%20--%3E%7C%E6%81%90%E6%85%8C%E7%AA%97%E5%8F%A3%7C%20B%5B%22%E5%9B%B4%E6%A0%8F%E6%94%B6%E7%B4%A7%20%2B%20%E9%97%A8%E6%8E%A7%20%2B%20%E6%9A%97%E8%85%BF%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20CASE%20--%3E%7C%E6%B6%A8%E8%B7%8C%E5%81%9C%7C%20C%5B%22%E5%81%9C%E6%97%B6%E6%A1%86%E6%9E%B6%20%2B%20%E6%9C%9F%E8%B4%A7%E6%8A%A4%E6%9A%B4%E9%9C%B2%20%2B%20%E7%95%99%E7%97%95%22%5D%0A%20%20A%20--%3E%20ACC%5B%22%E7%BB%9F%E4%B8%80%E5%88%B0%E8%BE%BE%E4%BB%B7%E4%BC%9A%E8%AE%A1%E4%B8%8E%E5%88%86%E5%B1%82%20TCA%22%5D%0A%20%20B%20--%3E%20ACC%0A%20%20C%20--%3E%20ACC%0A%20%20ACC%20--%3E%20REV%5B%22%E5%A4%8D%E7%9B%98%3A%20%E8%A3%81%E5%86%B3%E9%A1%BA%E5%BA%8F%E4%B8%8E%E6%B8%85%E5%8D%95%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"这套案例方法为什么有效：三个案例把「多条规则同时触发」的冲突提前搬上桌面，裁决顺序写成事前合同而不是临场判断——压力状态下执行者不缺规则，缺的是哪条让路的既定答案。清单能沉淀，是因为每个格子都挂着一门课的验收口径，案例只是把这些口径放进日历里互相牵制；复盘遇到裁决不了的新冲突，说明清单缺格，补格的动作本身构成课程与实战之间的反馈回路。",-1)),(e(),n(l,null,{default:E(()=>[i(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E4%B8%A4%E6%9D%A1%E8%A7%84%E5%88%99%E5%90%8C%E6%97%B6%E8%A7%A6%E5%8F%91%E4%B8%94%E5%8A%A8%E4%BD%9C%E7%9B%B8%E5%8F%8D%22%5D%20--%3E%20P1%7B%22%E4%BB%B7%E6%A0%BC%E4%BF%9D%E6%8A%A4%20vs%20%E5%AE%8C%E6%88%90%E7%8E%87%22%7D%0A%20%20P1%20--%3E%7C%E4%BB%B7%E6%A0%BC%E4%BF%9D%E6%8A%A4%E4%BC%98%E5%85%88%7C%20R1%5B%22%E5%B0%91%E5%AE%8C%E6%88%90%E8%AE%B0%E6%9C%BA%E4%BC%9A%E6%88%90%E6%9C%AC%EF%BC%8C%E4%B8%8D%E7%A9%BF%E4%BA%94%E6%A1%A3%22%5D%0A%20%20X%20--%3E%20P2%7B%22%E5%88%B6%E5%BA%A6%E7%BA%A6%E6%9D%9F%20vs%20%E6%A8%A1%E5%9E%8B%E6%9C%80%E4%BC%98%22%7D%0A%20%20P2%20--%3E%7C%E5%88%B6%E5%BA%A6%E4%BC%98%E5%85%88%7C%20R2%5B%22%E9%A1%BA%E5%BB%B6%E6%88%96%E6%94%BE%E5%BC%83%EF%BC%8C%E8%AE%B0%E5%88%B6%E5%BA%A6%E6%9C%AA%E5%AE%8C%E6%88%90%22%5D%0A%20%20X%20--%3E%20P3%7B%22%E7%95%99%E7%97%95%E4%B9%89%E5%8A%A1%20vs%20%E5%8F%82%E6%95%B0%E8%87%AA%E7%94%B1%22%7D%0A%20%20P3%20--%3E%7C%E7%95%99%E7%97%95%E4%BC%98%E5%85%88%7C%20R3%5B%22%E6%94%B9%E5%8D%95%E4%B8%8E%E6%92%A4%E5%8D%95%E9%80%90%E7%AC%94%E8%90%BD%E6%97%A5%E5%BF%97%22%5D%0A%20%20R1%20--%3E%20S%5B%22%E8%A3%81%E5%86%B3%E9%A1%BA%E5%BA%8F%E4%BA%8B%E5%89%8D%E5%86%99%E8%BF%9B%E7%8A%B6%E6%80%81%E6%9C%BA%22%5D%0A%20%20R2%20--%3E%20S%0A%20%20R3%20--%3E%20S%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">「机会成本 vs 永久成本」翻译成小白话：恐慌日少买到的部分，若价格后来回落，只是少赚，账面是机会成本；但为强行完成而穿过五档扫掉的每一档，是付出去就拿不回的永久成本。裁决规则因此偏向前者可以接受、后者必须避免。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>案例不可复制为参数：换市场、换品种、换规模，数字全部重估，可迁移的只有裁决顺序与清单结构。案例复盘存在幸存者偏差——写下来的多是处理成功的，失败案例按研究复盘的同模板归档才可检索。重申全课程的边界：执行是成本的工程，不是收益的来源；它把 alpha 完整地从决策送到持仓，而不是制造 alpha。把 TCA 的负滑点当策略，是把度量噪声当生产函数。</p><p><span class="marginnote">常见误区：把成功案例的参数当模板搬走。指数日的保守分位、恐慌日的围栏宽度都是在特定市场与规模下标定的；换品种换规模后原样照抄，等于把别人的药方当自己的诊断。可迁移的是裁决顺序与清单结构，不是数字。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>案例的价值在冲突裁决顺序：价格保护优先于完成率，制度约束优先于模型最优，留痕优先于参数自由。</li><li>指数日：配额、领先腿与保守分位成本合演；事后按日期类型单独分层。</li><li>恐慌窗口：预登记触发、毒性门控、暗腿压缩；少完成是机会成本，穿五档是永久成本。</li><li>涨跌停：吸收态加带停时的转换，期货护暴露，不可执行记成制度未完成。</li><li>沉淀物是一张十一个格子的清单：谱系、调度、场所、状态、度量、硬件、事前、控制。</li><li>执行把 alpha 完整地从决策送到持仓，不制造 alpha；本课程到此收束。</li><li>出处：Harris, <em>Trading and Exchanges</em>；Perold, <em>Journal of Portfolio Management</em>, 1988；各课口径见本课程对应链接。</li></ul>',6))])}const x=o(C,[["render",p]]);export{q as __pageData,x as default};
